import json
from collections import Counter
from typing import List, Tuple

def solve_observed(grid: Tuple[Tuple[int, ...], ...]) -> Tuple[Tuple[int, ...], ...]:
    rows = len(grid)
    cols = len(grid[0])

    # Background is most common
    all_cells = [c for r in grid for c in r]
    counts = Counter(all_cells)
    bg = counts.most_common(1)[0][0]

    # Foreground is the non-background color in rows that have it
    for r in range(rows):
        fg_row = [c for c in grid[r] if c != bg]
        if fg_row:
            fg = fg_row[0]
            break
    else:
        raise ValueError("No foreground found")

    """
    For each row:
    - If it has foreground but NOT at the right edge (last column),
      place 1s at positions: last_fg_col + 2, + 4, + 6, ... (until edge)
    """
    result = [list(row) for row in grid]

    for r in range(rows):
        foregrounds = [c for c in range(cols) if grid[r][c] == fg]
        if foregrounds:
            last_fg = max(foregrounds)
            # Check if last fg is NOT at the edge
            if grid[r][-1] != fg:
                # Place 1s in trailing background
                for delta in range(2, cols + 1, 2):  # 2, 4, 6, 8, ...
                    pos = last_fg + delta
                    if pos < cols and grid[r][pos] == bg:
                        result[r][pos] = 1
                    else:
                        break

    return tuple(tuple(row) for row in result)

def transform(grid: List[List[int]]) -> List[List[int]]:
    return solve_observed(tuple(tuple(row) for row in grid))

